/* Terrain stamp body for bank 7: array address arrives
 * in g_bk_ptr_b, the World in g_bk_ptr_a. Self-contained:
 * no fixed-bank calls (same rule as scene_load_tiles_banked).
 * Bounds checks are omitted deliberately: validate.py fails
 * loudly on out-of-bounds terrain blocks, so committed
 * content always fits (the home body keeps its own clamps). */
void terrain_stamp_b7_banked(void)
{
    World *w = (World *)g_bk_ptr_a;
    const SceneTerrainBlock *b = (const SceneTerrainBlock *)g_bk_ptr_b;
    uint8_t x, y;

    if (!w) return;
    for ( ; ; b++) {
        if (b->w == 0) break;
        for (y = b->y; y < (uint8_t)(b->y + b->h); y++) {
            uint8_t *row = w->map[y];
            for (x = b->x; x < (uint8_t)(b->x + b->w); x++) {
                row[x] = b->tile;
            }
        }
    }
}

